tool_input.command:
join /tmp/train_sorted.txt /tmp/serve_sorted.txt | awk '{
  # Check if log1p(serve_f1) ≈ train_f1
  import_cmd = "awk -v x=" $7 " '"'"'BEGIN{printf "%.6f", log(x+1)}'"'"'"
  tf1=$2; sf1=$7
  print $1, "tf1=" tf1, "sf1=" sf1, "log1p(sf1)=" log(sf1+1), "diff=" tf1-log(sf1+1)
}' | head -10
